        'Frontend'    => ['slug' => 'frontend',    'en' => 'Frontend & Mobile',       'ar' => 'الواجهات والموبايل'],
        'Platforms'   => ['slug' => 'platforms',   'en' => 'Platforms & Product',     'ar' => 'المنصات والمنتجات'],
    ];

